package vmcompat;
import java.nio.*;import java.nio.file.*;import org.lwjgl.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;
/** More unique real images than the cache: eviction must replace cache growth. */
public final class PackingEvictionTests {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s+" GL="+GL11.glGetError());}
 static int program(){return StorageBuffersTests.program("#version 330\nuniform sampler2D images[16];uniform sampler2D a;uniform sampler2D b;out vec4 c;void main(){vec4 sum=vec4(0);for(int i=0;i<16;i++)sum+=texture(images[i],vec2(.5));c=(sum+texture(a,vec2(.5))+texture(b,vec2(.5)))/18.;}");}
 static void draw(int p,int texture,float expected){Shaders.glUseProgram(p);Samplers.glActiveTexture(GL13.GL_TEXTURE0);Samplers.glBindTexture(GL11.GL_TEXTURE_2D,texture);for(int i=0;i<16;i++)Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"images["+i+"]"),0);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"a"),0);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"b"),0);Draws.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer pixel=BufferUtils.createFloatBuffer(4);GL11.glReadPixels(8,8,1,1,GL11.GL_RGBA,GL11.GL_FLOAT,pixel);check(Math.abs(pixel.get(0)-expected)<.008,"evicted/revisited image pixel "+pixel.get(0)+" != "+expected);check(Packing.failure()==null,"normal cache pressure must not stop renderer");check(GL11.glGetError()==0,"driver state");}
 public static void main(String[] a)throws Exception{check(GLFW.glfwInit(),"init");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long w=Context.createWindow(16,16,"Bounded cache replacement",0,0);Context.makeCurrent(w);Context.capabilities();GL11.glViewport(0,0,16,16);Draws.glBindVertexArray(GL30.glGenVertexArrays());int[] programs={program(),program()},images=new int[24];
  // Reuse CPU scratch; 24 source images total 96MiB, not unbounded source data.
  ByteBuffer pixels=BufferUtils.createByteBuffer(1024*1024*4);for(int i=0;i<images.length;i++){int value=8+i*8;pixels.clear();for(int k=0;k<1024*1024;k++)pixels.put(new byte[]{(byte)value,0,0,(byte)255});pixels.flip();int t=images[i]=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(t,1,GL11.GL_RGBA8,1024,1024);Textures.glTextureParameteri(t,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST);Textures.glTextureParameteri(t,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);Textures.glTextureSubImage2D(t,0,0,0,1024,1024,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,pixels);}
  long allocations=-1;for(int turn=0;turn<3;turn++){for(int i=0;i<images.length;i++)for(int p:programs)draw(p,images[i],(8+i*8)/255f);GL11.glFinish();long now=Packing.memoryStats()[2];if(turn==0)allocations=now;else check(now==allocations,"streaming/revisiting must not allocate after cache warmup");}
  long[] m=Packing.memoryStats();check(m[6]>0,"fixture must actually force LRU eviction");check(m[0]<144L*1024*1024,"two cache pools remain bounded near 128MiB");
  ByteBuffer change=BufferUtils.createByteBuffer(4).put(new byte[]{(byte)224,0,0,(byte)255}).flip();Textures.glTextureSubImage2D(images[0],0,512,512,1,1,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,change);for(int p:programs)draw(p,images[0],224/255f);
  Files.writeString(Path.of(System.getProperty("vmcompat.resultDir"),"eviction.json"),"{\"source_images\":24,\"programs\":2,\"passes\":3,\"draws\":144,\"reserved\":"+m[0]+",\"peak_reserved\":"+m[1]+",\"evictions\":"+m[6]+",\"rebuilds\":"+m[7]+",\"allocations_after_warm\":0,\"pixels_correct\":true,\"failure\":null,\"game_fps\":null}\n");
  for(int p:programs)Shaders.glDeleteProgram(p);Textures.glDeleteTextures(images);Context.destroyWindow(w);GLFW.glfwTerminate();check(Packing.memoryStats()[0]==0,"all cache allocations released");System.out.println("PASS bounded cache eviction, 24 images / 2 programs / 144 draws, revisits and mutation");
 }
}
